const SJT_APPROPRIATENESS_OPTIONS = [
  { key: "A" as const, text: "A very appropriate thing to do" },
  { key: "B" as const, text: "Appropriate, but not ideal" },
  { key: "C" as const, text: "Inappropriate, but not awful" },
  { key: "D" as const, text: "A very inappropriate thing to do" },
];

const SJT_IMPORTANCE_OPTIONS = [
  { key: "A" as const, text: "Very important" },
  { key: "B" as const, text: "Important" },
  { key: "C" as const, text: "Of minor importance" },
  { key: "D" as const, text: "Not important at all" },
];

function getSjtOptions(subtype: string) {
  return subtype === "sjt-appropriateness"
    ? SJT_APPROPRIATENESS_OPTIONS
    : SJT_IMPORTANCE_OPTIONS;
}

function buildCuratedSjtInput(
  input: SjtCuratedInput,
  inputIndex: number
): UCATQuestion[] {
  if (input.kind === "single") {
    return [
      {
        id: `user-curated-sjt-${String(inputIndex + 1).padStart(4, "0")}-1`,
        section: "sjt" as const,
        subtype: input.subtype,
        tags: input.tags ?? ["text-stem", "medium"],
        issueTags: input.issueTags,
        title: "Situational Judgement Practice",
        leftTitle: "Scenario",
        stimulus: input.stimulus,
        question: input.question,
        options: getSjtOptions(input.subtype),
        answer: input.answer,
        explanation: input.explanation,
      },
    ];
  }
  const setId = `user-curated-sjt-${String(inputIndex + 1).padStart(4, "0")}`;
  return input.questions.map((q, qIndex) => ({
    id: `${setId}-${qIndex + 1}`,
    section: "sjt" as const,
    subtype: q.subtype,
    setId,
    tags: input.tags ?? ["text-stem", "set-based", "medium"],
    issueTags: input.issueTags,
    title: "Situational Judgement Practice",
    leftTitle: "Scenario",
    stimulus: input.stimulus,
    question: q.question,
    options: getSjtOptions(q.subtype),
    answer: q.answer,
    explanation: q.explanation,
  }));
}

function buildRawSjtSet(raw: SjtRawInput, setIndex: number): UCATQuestion[] {
  const setId = `user-raw-sjt-${String(setIndex + 1).padStart(4, "0")}`;
  return raw.questions.map((q, qIndex) => ({
    id: `${setId}-${qIndex + 1}`,
    section: "sjt" as const,
    subtype: q.subtype,
    setId,
    tags: ["text-stem", "set-based", "medium"] as UCATQuestionTag[],
    issueTags: raw.issueTags ?? [],
    title: "Situational Judgement Practice",
    leftTitle: "Scenario",
    stimulus: [raw.stem],
    question: q.question,
    options: getSjtOptions(q.subtype),
    answer: q.answer,
    explanation: q.explanation,
  }));
}

export const CURATED_SJT_QUESTIONS: UCATQuestion[] = [
  ...USER_CURATED_SJT_INPUTS.flatMap(buildCuratedSjtInput),
  ...USER_RAW_SJT_INPUTS.flatMap(buildRawSjtSet),
];
